from pathlib import Path
p=Path('management.js');s=p.read_text(encoding='utf-8-sig');a=s.index('<div class="knowledge-top">');b=s.index('<el-table :data="filteredDocs',a)
new='''<header class="keyword-heading"><h1>知識文件列表</h1><el-dropdown @command="newDocument" trigger="click"><el-button type="primary">新增知識文件</el-button><el-dropdown-menu slot="dropdown"><el-dropdown-item command="general">一般</el-dropdown-item><el-dropdown-item command="ai">AI</el-dropdown-item></el-dropdown-menu></el-dropdown></header>
<form class="knowledge-filter knowledge-search-panel" @submit.prevent="query=search.trim();page=1" aria-label="知識文件搜尋">
<div class="knowledge-search-row"><div class="knowledge-search-field"><label for="knowledge-main-filter">主分類</label><el-select id="knowledge-main-filter" v-model="filterMain" placeholder="全部" clearable @change="filterSub=''" aria-label="主分類篩選"><el-option v-for="g in knowledge" :key="g.value" :label="g.label" :value="g.value"></el-option></el-select></div><div class="knowledge-search-field"><label for="knowledge-sub-filter">次分類</label><el-select id="knowledge-sub-filter" v-model="filterSub" placeholder="全部" clearable :disabled="!filterMain" aria-label="次分類篩選"><el-option v-for="s in filterSubs" :key="s.value" :label="s.label" :value="s.value"></el-option></el-select></div><div class="knowledge-search-field"><label for="knowledge-keyword">關鍵字</label><el-input id="knowledge-keyword" v-model="search" placeholder="請輸入搜尋關鍵字" clearable></el-input></div><el-button type="primary" native-type="submit">搜尋</el-button></div>
<div class="knowledge-search-row"><div class="knowledge-search-field"><span id="knowledge-status-label">啟用狀態</span><el-radio-group v-model="status" aria-labelledby="knowledge-status-label"><el-radio label="all">所有狀態</el-radio><el-radio :label="true">啟用</el-radio><el-radio :label="false">停用</el-radio></el-radio-group></div><div class="knowledge-search-field"><span id="knowledge-kind-label">文件類型</span><el-radio-group v-model="kind" aria-labelledby="knowledge-kind-label"><el-radio label="general">一般知識文件</el-radio><el-radio label="ai">AI 知識文件</el-radio></el-radio-group></div></div>
</form>
'''
s=s[:a]+new+s[b:];p.write_text(s,encoding='utf-8')
